        path.push(index);
        visit(result.state, depth + 1);
        path.pop();
      }

      verify(state.board.every((cell, index) => cell === boardBefore[index])
        && state.nextPlayer === nextBefore && state.outcome === outcomeBefore, "Input state was mutated");
      if (legalMoves.length === 0) {
        counts.total += 1;
